package server

import (
	"context"
	"errors"
	"path/filepath"
	"testing"

	archive "proxycontrol/internal/panel/system/backup"
	"proxycontrol/internal/platform/config"
	"proxycontrol/internal/platform/db"
)

// TestPreBaselineBackupIsRefused stages a backup archive produced by the
// pre-refactor baseline (commit de6a681, long before v1.6.0). Since v1.6.1 the
// migration chain starts at the v1.6.0 baseline, so such an archive must be
// refused before anything is restored.
//
// The fixture was generated by internal/platform/server/testdata/generate_prerefactor.
func TestPreBaselineBackupIsRefused(t *testing.T) {
	t.Parallel()
	ctx := context.Background()
	archivePath := filepath.Join("testdata", "prerefactor_backup.pcb")
	const password = "fixture-backup-password"
	targetDirectory := t.TempDir()
	panel := config.DefaultPanel()
	panel.Database = filepath.Join(targetDirectory, "panel.db")
	panel.NodeIdentityDirectory = filepath.Join(targetDirectory, "identity")
	_, err := archive.PrepareRestore(ctx, t.TempDir(), archivePath, password, archive.RestoreTarget{Panel: panel, ConfigurationPath: filepath.Join(targetDirectory, "panel.yaml")})
	if !errors.Is(err, db.ErrPredatesBaseline) || !errors.Is(err, archive.ErrArchive) {
		t.Fatalf("old archive not refused as predating the baseline: %v", err)
	}
}
